/* Layout for this component's own nodes.
   These were per-node `styles` overrides. Past a certain number of them in
   one document the browser stops matching the compiled
   [data-bz-node="x"][data-bz-node] rules — some apply and some silently do
   not — so the same declarations live here instead, where they hold. See the
   note in the commit message; this is a platform bug worth fixing upstream.
   ------------------------------------------------------------------------- */
[data-bz-node="banner-band"]{padding-top:100px;padding-bottom:120px}
[data-bz-node="banner-copy-col"]{display:flex;flex-direction:column;justify-content:center;padding-top:56px;padding-right:56px;padding-bottom:56px;padding-left:56px}
@media (max-width: 640px){
[data-bz-node="banner-band"]{padding-top:56px;padding-bottom:64px}
[data-bz-node="banner-copy-col"]{padding-top:32px;padding-right:20px;padding-bottom:32px;padding-left:20px}
}

/* ----------------------------------------------------------------- BANNER ---
   The whole two-up sits inside one hairline box, with a second hairline
   between the panes. The photograph pane has a minimum height so the box
   keeps its proportion when the copy is short. */

[data-bz-node="banner-band"] .bz-block { padding-block: 0; }
[data-bz-node="banner-row"] { border: 1px solid var(--line); }
[data-bz-node="banner-media-col"] { border-left: 1px solid var(--line); min-height: 340px; }

[data-bz-node="banner-heading"] h2 { font: 800 var(--text-h3) / 1.2 var(--font-heading); margin: 0 0 16px; }
.bz-block[data-bz-node="banner-heading"] p.bz-eyebrow { margin: 0 0 16px; }
[data-bz-node="banner-body"] { margin-bottom: 28px; }
[data-bz-node="banner-body"] p { font-size: var(--text-base, 15px); line-height: 1.6; }
[data-bz-node="banner-body"] .bz-text { max-width: none; }

[data-bz-node="banner-media-col"], [data-bz-node="banner-media"],
[data-bz-node="banner-media"] .bz-container, [data-bz-node="banner-media"] figure { height: 100%; }
[data-bz-node="banner-media"] img {
  width: 100%; height: 100%;
  object-fit: cover; object-position: center;
  display: block;
}

/* Which side the photograph sits on is set per placement, in the page CSS —
   a component prop cannot reach a stylesheet, and reordering the DOM would
   put the photograph before the copy for a screen reader. */

@media (max-width: 640px) {
  [data-bz-node="banner-media-col"] { border-left: 0; min-height: 180px; }
}
